from math import comb

def calculate_ratio(n):
    # f(K_n) = number of triangles (C3) = comb(n, 3)
    f_Kn = comb(n, 3)

    # g(K_n) = number of C4 cycles in K_n = 3 * comb(n, 4)
    # Note: comb(n, 4) is 0 if n < 4
    g_Kn = 3 * comb(n, 4)

    if f_Kn == 0:
        return "Undefined (f(K_n) is zero)"

    ratio = (g_Kn**3) / (f_Kn**4)
    return ratio, f_Kn, g_Kn

N_values = [3, 4, 5, 6]
results = {}

for n in N_values:
    result = calculate_ratio(n)
    results[n] = result

for n, (ratio, f, g) in results.items():
    if isinstance(ratio, str):
        print(f"N={n}: {ratio}")
    else:
        # Print as fraction if possible or high precision float
        print(f"N={n}: Ratio = {ratio:.6f} (F={f}, G={g})")

from math import comb

# Function to calculate R(G) for a complete graph K_n
def calculate_ratio_kn(n):
    if n < 4:
        return float('nan')
    f_g = comb(n, 3)
    g_g = comb(n, 4)
    if f_g == 0:
        return float('inf')
    return (g_g**3) / (f_g**4)

print(f"R(K4) = {calculate_ratio_kn(4)}")
print(f"R(K5) = {calculate_ratio_kn(5)}")
print(f"R(K6) = {calculate_ratio_kn(6)}")

